// ===================================
// submitObs — public HTTP endpoint for the mess-room QR form.
//
// GET  /submitObs?token=<obsToken>   → { name: "DreamBoat" }  (vessel name for the form header)
// POST /submitObs                    body { token, kind, topic, location?, what, name? }  → { ok: true }
//
// The token is stored on the vessel document as `obsToken`. It is generated by the
// Master from the QHSE screen and saved to Firestore from the app; the function
// validates it here on the server so the IMO never travels to the browser.
//
// Anyone who reaches the URL may submit. No enrolment, no Firebase SDK on the phone.
// The resulting observation carries `via: 'qr'` and is always anonymous unless the
// person adds their name voluntarily.
// ===================================

const { onRequest } = require('firebase-functions/v2/https');
const admin = require('firebase-admin');

const REGION = 'europe-west1';
const ROOT = 'safety_vessels';
const VALID_KINDS = ['unsafe_act', 'unsafe_condition', 'near_miss', 'good_practice'];
const CORS_ORIGINS = ['https://app.ismpilot.com', 'http://localhost:8081', 'http://localhost:19006'];

function cors(req, res) {
  const origin = req.headers.origin ?? '';
  if (CORS_ORIGINS.includes(origin)) res.set('Access-Control-Allow-Origin', origin);
  res.set('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.set('Access-Control-Allow-Headers', 'Content-Type');
}

async function findVessel(token) {
  if (!token || typeof token !== 'string' || token.length < 8) return null;
  const snap = await admin.firestore().collection(ROOT).where('obsToken', '==', token).limit(1).get();
  return snap.empty ? null : snap.docs[0];
}

module.exports = {
  submitObs: onRequest({ region: REGION }, async (req, res) => {
    cors(req, res);
    if (req.method === 'OPTIONS') { res.sendStatus(204); return; }

    const token = req.method === 'GET' ? String(req.query.token ?? '') : (req.body?.token ?? '');
    const doc = await findVessel(token);
    if (!doc) { res.status(404).json({ error: 'unknown token' }); return; }

    if (req.method === 'GET') {
      const d = doc.data();
      res.json({ name: d.obsVesselName ?? d.vessel_name ?? '' });
      return;
    }

    if (req.method !== 'POST') { res.status(405).json({ error: 'method not allowed' }); return; }

    const { kind, topic, location, what, name } = req.body ?? {};
    if (!VALID_KINDS.includes(kind)) { res.status(400).json({ error: 'invalid kind' }); return; }
    if (!topic || typeof topic !== 'string' || !topic.trim()) { res.status(400).json({ error: 'topic required' }); return; }
    if (!what || typeof what !== 'string' || what.trim().length < 3) { res.status(400).json({ error: 'what required (min 3 chars)' }); return; }

    const now = Date.now();
    const today = new Date().toISOString().slice(0, 10);
    const id = admin.firestore().collection('_').doc().id;
    const nameStr = typeof name === 'string' ? name.trim() : '';

    const obs = {
      id,
      date: today,
      kind,
      topic: topic.trim(),
      what: what.trim(),
      anonymous: !nameStr,
      via: 'qr',
      at: now,
      updatedAt: now,
    };
    if (location && typeof location === 'string' && location.trim()) obs.location = location.trim();
    if (nameStr) obs.by = nameStr;

    await admin.firestore().collection(ROOT).doc(doc.id).collection('observations').doc(id).set(obs);
    res.json({ ok: true });
  }),
};
